use crate::cli::Algorithm;use sha2::{Digest,Sha256,Sha512};use std::{fs::File,io::{self,BufReader,Read},path::Path};
pub fn hash_file(path:&Path,algorithm:Algorithm)->io::Result<String>{let mut reader=BufReader::new(File::open(path)?);let mut buf=[0u8;65536];match algorithm{Algorithm::Sha256=>{let mut h=Sha256::new();loop{let n=reader.read(&mut buf)?;if n==0{break}h.update(&buf[..n])}Ok(format!("{:x}",h.finalize()))},Algorithm::Sha512=>{let mut h=Sha512::new();loop{let n=reader.read(&mut buf)?;if n==0{break}h.update(&buf[..n])}Ok(format!("{:x}",h.finalize()))}}}
#[cfg(test)]mod tests{use super::*;use crate::cli::Algorithm;use std::io::Write;#[test]fn hashes_known_bytes(){let mut f=tempfile::NamedTempFile::new().unwrap();write!(f,"abc").unwrap();assert_eq!(hash_file(f.path(),Algorithm::Sha256).unwrap(),"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")}}
